// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract ReentrantAttacker {
    Reentrance private c;
    bool private entered;

    constructor(Reentrance _c) {
        c = _c;
    }

    function attack() external payable {
        c.addToBalance{value: msg.value}();
        c.withdrawBalance();
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            c.withdrawBalance();
        }
    }
}

contract InvMutTest is Test {
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function testFuzz_property(uint256 amount, uint256 victimDeposit) public {
        vm.assume(victimDeposit <= VALUE_CAP);
        vm.assume(amount <= VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(amount <= 100 ether);
        vm.assume(victimDeposit > 0);
        vm.assume(victimDeposit <= 100 ether);

        ReentrantAttacker attacker = new ReentrantAttacker(c);
        address victim = address(0xBEEF);

        vm.deal(victim, victimDeposit);
        vm.prank(victim);
        c.addToBalance{value: victimDeposit}();

        assertEq(c.getBalance(victim), victimDeposit, "victim deposit should be recorded");
        assertEq(address(c).balance, victimDeposit, "contract should hold victim deposit");

        vm.deal(address(attacker), amount);
        attacker.attack{value: amount}();

        assertEq(
            address(c).balance,
            victimDeposit,
            "contract must retain the victim's pre-existing Ether after a re-entrant withdrawal"
        );
    }
}
